class Solution {
public:
    int minReorder(int n, vector<vector<int>>& connections) {
        vector<vector<pair<int,int>>> adj(n);
        for (auto& c : connections) {
            int a = c[0], b = c[1];
            adj[a].push_back({b, 1}); // original direction a -> b
            adj[b].push_back({a, 0}); // reverse direction b -> a
        }
        int ans = 0;
        vector<bool> seen(n, false);
        seen[0] = true;
        vector<pair<int,int>> st;
        st.push_back({0, -1});
        while (!st.empty()) {
            pair<int,int> top = st.back();
            st.pop_back();
            int u = top.first;
            for (int i = 0; i < (int)adj[u].size(); ++i) {
                int v = adj[u][i].first;
                int d = adj[u][i].second;
                if (!seen[v]) {
                    seen[v] = true;
                    ans += d;
                    st.push_back({v, u});
                }
            }
        }
        return ans;
    }
};
